// Controller only: calls already verified G/A, never L or M.
use serde_json::{Value,json};
use water_scan_report::v1::{ReportContext,ScopeContext,assemble_json};
fn context(v:&Value)->ReportContext{ReportContext{scan_id:water_contracts::v1::OpaqueId::new(v["scan_id"].as_str().unwrap()).unwrap(),platform:serde_json::from_value(v["platform"].clone()).unwrap(),scopes:v["scopes"].as_array().unwrap().iter().map(|s|ScopeContext{scope_id:water_contracts::v1::OpaqueId::new(s["scope_id"].as_str().unwrap()).unwrap(),label:s["label"].as_str().unwrap().to_owned(),origin:serde_json::from_value(s["origin"].clone()).unwrap()}).collect()}}
fn main(){let seeds:Value=serde_json::from_str(include_str!("../../contracts/evidence-batch-v1/seeds.json")).unwrap();let mut cases=Vec::new();for kind in ["project_evidence","size_ledger"]{for c in seeds[kind].as_array().unwrap(){let bundle=assemble_json(&c["input"].to_string(),&context(&c["context"])).unwrap();assert_eq!(bundle.source_facts(),&c["input"]);let encoded=water_contracts::v1::to_json(bundle.report()).unwrap();assert_eq!(water_contracts::v1::parse_report(&encoded).unwrap(),*bundle.report());cases.push(json!({"kind":kind,"id":c["id"],"bundle":bundle}));}}let mut errors=Vec::new();for c in seeds["source_errors"].as_array().unwrap(){let e=assemble_json(c["input"].as_str().unwrap(),&context(&c["context"])).unwrap_err();assert_eq!(format!("{:?}",e.code),c["code"].as_str().unwrap(),"{}",c["id"]);assert_eq!(e.field,c["field"].as_str().unwrap());assert!(!format!("{e:?} {e}").contains("LM_ERROR_CANARY"));errors.push(json!({"id":c["id"],"code":format!("{:?}",e.code),"field":e.field}));}println!("{}",json!({"cases":cases,"errors":errors,"new_products_tested":false}));}
